def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_opp = False
    needy_opp = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                needy_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = float(prev.get('bid', 0.0))
                prev_bids.append(b)
                if b >= 120:
                    strong_opp = True
            if opp.get('budget', 0) > budget * 1.5 and opp.get('hp', 0) >= hp:
                strong_opp = True

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    pressure = 0.0
    if slots <= 1:
        pressure += 1.0
    elif slots == 2:
        pressure += 0.55
    else:
        pressure += 0.2

    if len(alive) > slots:
        pressure += 0.35
    if strong_opp:
        pressure += 0.35
    if needy_opp > 0:
        pressure += 0.15
    if hp <= 2:
        pressure += 0.9
    elif hp <= 4:
        pressure += 0.45
    if no_water >= 1:
        pressure += 0.5
    if day >= 8:
        pressure += 0.15

    top_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if hp <= 1 or no_water >= 2:
        bid = min(budget, max(95.0, top_prev + 3.0, DAILY_SALARY * 1.15))
        return max(0.0, bid)

    if pressure >= 1.8:
        target = max(78.0, min(110.0, avg_prev * 0.75 + 18.0, top_prev + 2.5))
    elif pressure >= 1.2:
        target = max(52.0, min(82.0, avg_prev * 0.55 + 10.0, top_prev * 0.7 + 6.0))
    elif pressure >= 0.8:
        target = max(30.0, min(58.0, avg_prev * 0.4 + 6.0))
    else:
        target = 18.0 if hp > 5 else 26.0

    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0:
        keep = reserve_days * 18.0
        soft_cap = max(0.0, budget - keep)
        if hp <= 3:
            soft_cap = budget

    if soft_cap < 8.0:
        soft_cap = min(budget, max(8.0, budget * 0.6))

    bid = min(budget, min(target, soft_cap))
    if hp <= 3 and bid < 42.0:
        bid = min(budget, 42.0)
    if slots <= 1 and hp <= 4:
        bid = min(budget, max(bid, 68.0))

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    base_bid = DAILY_SALARY * 0.5
    if current_day > EPISODE_DAYS / 2:
        base_bid = DAILY_SALARY * 0.65

    if my_hp <= 2 or my_no_water_days > 0:
        base_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)

    highest_prev_bid = 0.0
    num_desperate_opponents = 0

    for opp in alive_opponents:
        if opp['hp'] <= 2 or opp['no_water_days'] > 0:
            num_desperate_opponents += 1

        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid * 1.05)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            base_bid = max(base_bid, highest_prev_bid + (DAILY_SALARY * 0.05))
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.55)

    if num_desperate_opponents > 0:
        base_bid = max(base_bid, DAILY_SALARY * (0.7 + num_desperate_opponents * 0.05))
        base_bid = min(base_bid, DAILY_SALARY * 0.98)

    total_water_needed_by_alive = WATER_REQ + sum(o['water_requirement'] for o in alive_opponents)

    if current_supply < total_water_needed_by_alive:
        supply_shortage_ratio = (total_water_needed_by_alive - current_supply) / total_water_needed_by_alive
        base_bid *= (1 + supply_shortage_ratio * 0.3)

    final_bid = min(my_budget, base_bid)
    final_bid = max(final_bid, DAILY_SALARY * 0.05)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if my_status['hp'] < 4:
            return float(min(my_status['budget'], max(highest_prev_bid + 2.0, DAILY_SALARY * 0.9)))
        if highest_prev_bid > DAILY_SALARY * 1.2:
            return float(min(my_status['budget'], DAILY_SALARY * 0.3))
        return float(min(my_status['budget'], max(DAILY_SALARY * 0.55, highest_prev_bid + 1.0)))
    return float(min(my_status['budget'], DAILY_SALARY * 0.6))
